{"code": "async function main() {
  // Try different item names
  const itemsToTry = ["charcoal", "torch", "wood", "plank", "wooden_plank", "stick", "coal"];

  for (const item of itemsToTry) {
    try {
      const result = await tools.mcp_skillcraft_s6.place({ item: item, slot: 0 });
      console.log(`Placed ${item}:`, JSON.stringify(result));
      // Take it back
      await tools.mcp_skillcraft_s6.take({ slot: 0 });
      break;
    } catch (e) {
      console.log(`Cannot place ${item}:`, e.message);
    }
  }

  return "done";
}"}

